static void _dmsetup_usage(FILE *out)
{
	unsigned i;

	fprintf(out, "Usage:\n\n"
		"%s\n\t"
		"[--version] [-h|--help [-c|-C|--columns]]\n\t"
		"[-v|--verbose [-v|--verbose ...]] [-f|--force]\n\t"
