static void _usage(FILE *out)
{
	switch (_base_commands[_base_command].type) {
	case DMSETUP_TYPE:
		_dmsetup_usage(out);
		break;
	case LOSETUP_TYPE:
		_losetup_usage(out);
		break;
	case STATS_TYPE:
		_stats_usage(out);
		break;
	case DEVMAP_NAME_TYPE:
		_devmap_name_usage(out);
		break;
	case VDOSTATS_TYPE:
		_vdostats_usage(out);
		break;
	}
}

